 * A small hand-written scanner for the language described in the task
 * prompt. `scan(input)` turns UTF-8 source text into an array of tokens, or
 * throws a `LexError` describing the first place the input stops scanning.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCTS = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCTS = new Set('+-*/%=<>!(){}[],;.')

function isLetter(c) {
  return c !== undefined && /[A-Za-z]/.test(c)
}

function isDigit(c) {
  return c !== undefined && /[0-9]/.test(c)
}

function isIdentPart(c) {
  return c !== undefined && /[A-Za-z0-9_]/.test(c)
}

function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}

export class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

/**
 * Scans `input`, an entire UTF-8 source text, into tokens. Each token is
 * `{ line, col, kind, text }` where `text` is the raw source text of the
 * token for every kind except `string` and `rawstring`, whose `text` is the
 * decoded value (a JS string, not yet JSON-encoded).
 */
export function scan(input) {
  const chars = Array.from(input)
  const n = chars.length
  let pos = 0
  let line = 1
  let col = 1

  function advance() {
    const c = chars[pos]
    pos++
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = (Math.floor((col - 1) / 4) + 1) * 4 + 1
    } else {
      col++
    }
    return c
  }

  function fail(l, c, reason) {
    throw new LexError(l, c, reason)
  }

  function scanLineComment() {
    advance()
    advance()
    while (pos < n && chars[pos] !== '\n') advance()
  }

  function scanBlockComment() {
    const startLine = line
    const startCol = col
    advance()
    advance()
    let depth = 1
    while (depth > 0) {
      if (pos >= n) fail(startLine, startCol, 'unterminated block comment')
      if (chars[pos] === '/' && chars[pos + 1] === '*') {
        advance()
        advance()
        depth++
      } else if (chars[pos] === '*' && chars[pos + 1] === '/') {
        advance()
        advance()
        depth--
      } else {
        advance()
      }
    }
  }

  function scanIdent() {
    const startLine = line
    const startCol = col
    let text = ''
    while (pos < n && isIdentPart(chars[pos])) text += advance()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { line: startLine, col: startCol, kind, text }
  }

  function scanDigitsWithUnderscore(digitTest, text) {
    let lastWasDigit = true
    while (pos < n) {
      const c = chars[pos]
      if (digitTest(c)) {
        text += advance()
        lastWasDigit = true
      } else if (c === '_' && lastWasDigit && digitTest(chars[pos + 1])) {
        text += advance()
        lastWasDigit = false
      } else {
        break
      }
    }
    return text
  }

  function scanNumber() {
    const startLine = line
    const startCol = col
    let text = ''
    const first = chars[pos]
    text += advance()

    let ok = true

    if (first === '0' && /[xXbBoO]/.test(chars[pos] ?? '')) {
      const p = chars[pos].toLowerCase()
      text += advance()
      const digitTest = p === 'x' ? isHexDigit : p === 'b' ? (c) => c === '0' || c === '1' : (c) => c !== undefined && /[0-7]/.test(c)
      const before = text.length
      text = scanDigitsWithUnderscore(digitTest, text)
      if (text.length === before) ok = false
    } else {
      text = scanDigitsWithUnderscore(isDigit, text)
      if (chars[pos] === '.' && isDigit(chars[pos + 1])) {
        text += advance()
        text = scanDigitsWithUnderscore(isDigit, text)
      }
      if (chars[pos] === 'e' || chars[pos] === 'E') {
        let idx = pos + 1
        let hasSign = false
        if (chars[idx] === '+' || chars[idx] === '-') {
          hasSign = true
          idx++
        }
        if (isDigit(chars[idx])) {
          text += advance()
          if (hasSign) text += advance()
          text = scanDigitsWithUnderscore(isDigit, text)
        }
      }
    }

    let hadTrailing = false
    if (pos < n && isIdentPart(chars[pos])) {
      hadTrailing = true
      while (pos < n && isIdentPart(chars[pos])) text += advance()
    }

    if (!ok || hadTrailing) fail(startLine, startCol, `invalid number ${text}`)

    return { line: startLine, col: startCol, kind: 'number', text }
  }

  function scanStringEscape(openLine, openCol) {
    const backslashLine = line
    const backslashCol = col
    advance() // consume backslash
    if (pos >= n) fail(openLine, openCol, 'unterminated string')
    const esc = chars[pos]
    switch (esc) {
      case 'n':
        advance()
        return '\n'
      case 't':
        advance()
        return '\t'
      case 'r':
        advance()
        return '\r'
      case '\\':
        advance()
        return '\\'
      case '"':
        advance()
        return '"'
      case '0':
        advance()
        return '\0'
      case 'x': {
        advance()
