        while (pos < n && isHexDigit(chars[pos])) hex += advance()
        if (hex.length === 0) fail(backslashLine, backslashCol, 'invalid escape \\u')
        if (pos >= n) fail(openLine, openCol, 'unterminated string')
        if (chars[pos] !== '}') fail(backslashLine, backslashCol, 'invalid escape \\u')
        advance()
        const codePoint = parseInt(hex, 16)
        if (codePoint > 0x10ffff) fail(backslashLine, backslashCol, 'invalid escape \\u')
        return String.fromCodePoint(codePoint)
      }
      default:
        fail(backslashLine, backslashCol, `invalid escape \\${esc}`)
        return '' // unreachable
    }
  }

  function scanString() {
    const startLine = line
    const startCol = col
    advance() // consume opening quote
    let value = ''
    for (;;) {
      if (pos >= n) fail(startLine, startCol, 'unterminated string')
      const c = chars[pos]
      if (c === '"') {
        advance()
        break
      }
      if (c === '\n') fail(line, col, 'newline in string')
      if (c === '\\') {
        value += scanStringEscape(startLine, startCol)
        continue
      }
      value += advance()
    }
    return { line: startLine, col: startCol, kind: 'string', text: value }
  }

  function scanRawString() {
    const startLine = line
    const startCol = col
    advance() // consume 'r'
    advance() // consume opening quote
    let value = ''
    for (;;) {
      if (pos >= n) fail(startLine, startCol, 'unterminated string')
      const c = chars[pos]
      if (c === '"') {
        advance()
        break
      }
      value += advance()
    }
    return { line: startLine, col: startCol, kind: 'rawstring', text: value }
  }

  const tokens = []

  while (pos < n) {
    const c = chars[pos]

    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      advance()
      continue
    }

    if (c === '/' && chars[pos + 1] === '/') {
      scanLineComment()
      continue
    }

    if (c === '/' && chars[pos + 1] === '*') {
      scanBlockComment()
      continue
    }

    if (c === 'r' && chars[pos + 1] === '"') {
      tokens.push(scanRawString())
      continue
    }

    if (isLetter(c) || c === '_') {
      tokens.push(scanIdent())
      continue
    }

    if (isDigit(c)) {
      tokens.push(scanNumber())
      continue
    }

    if (c === '"') {
      tokens.push(scanString())
      continue
    }

    const startLine = line
    const startCol = col
    const two = c + (chars[pos + 1] ?? '')
    if (TWO_CHAR_PUNCTS.includes(two)) {
      advance()
      advance()
      tokens.push({ line: startLine, col: startCol, kind: 'punct', text: two })
      continue
    }

    if (ONE_CHAR_PUNCTS.has(c)) {
      advance()
      tokens.push({ line: startLine, col: startCol, kind: 'punct', text: c })
      continue
    }

    fail(startLine, startCol, `unexpected character ${c}`)
  }

  return tokens
}
