// from the spec text, used to cross-check the scanner's accept/reject
// decisions and the exact text it consumes.
function refNumber(s, start) {
  // Returns { ok: true, text } or { ok: false, text } (text = everything consumed)
  let i = start
  const n = s.length
  const isDigit = (c) => c !== undefined && /[0-9]/.test(c)
  const isHex = (c) => c !== undefined && /[0-9a-fA-F]/.test(c)
  const isBin = (c) => c === '0' || c === '1'
  const isOct = (c) => c !== undefined && /[0-7]/.test(c)
  const isIdentPart = (c) => c !== undefined && /[A-Za-z0-9_]/.test(c)

  function digitRun(test) {
    // consumes a run of test-digits with underscore rule; returns count of digits consumed
    let count = 0
    let lastWasDigit = false
    while (i < n) {
      if (test(s[i])) {
        i++
        count++
        lastWasDigit = true
      } else if (s[i] === '_' && lastWasDigit && test(s[i + 1])) {
        i++
        lastWasDigit = false
      } else break
    }
    return count
  }

  const first = s[i]
  i++
  let ok = true
  if (first === '0' && /[xXbBoO]/.test(s[i] ?? '')) {
    const p = s[i].toLowerCase()
    i++
    const test = p === 'x' ? isHex : p === 'b' ? isBin : isOct
    const count = digitRun(test)
    if (count === 0) ok = false
  } else {
    digitRun(isDigit)
    if (s[i] === '.' && isDigit(s[i + 1])) {
      i++
      digitRun(isDigit)
    }
    if (s[i] === 'e' || s[i] === 'E') {
      let j = i + 1
      let sign = false
      if (s[j] === '+' || s[j] === '-') {
        sign = true
        j++
      }
      if (isDigit(s[j])) {
        i++
        if (sign) i++
        digitRun(isDigit)
      }
    }
  }

  let hadTrailing = false
  if (i < n && isIdentPart(s[i])) {
    hadTrailing = true
    while (i < n && isIdentPart(s[i])) i++
  }

